/// 🧭️ The caller obtains each read from the original qualified drawing_read_at and keeps its provider loan alive for returned descriptors.
pub struct DrawingPlanCursor{address:DrawingSourceAddress,placement:DrawingPlacement,target:LayoutBounds,preparation:Option<OriginalChildVectorPreparation>,phase:Phase,frames:PagedList<Frame,{usize::MAX}>,pending:Option<Frame>,root:usize,leaf:usize,text_index:usize,measuring:bool,bounds:Option<DrawingBounds>,fit:DrawingAffine,path:DrawingPathBounds,asset:usize,sample:Option<usize>,last:VectorSceneReceipt,closing:bool,closed:bool}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn g(g:VectorSceneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:g.maximum_source_items,maximum_copy_bytes:g.maximum_copy_bytes,maximum_capacity_bytes:g.maximum_capacity_bytes,maximum_release_bytes:g.maximum_release_bytes,maximum_depth:g.maximum_depth}}
fn receipt(p:RetainedCloneProgress)->VectorSceneReceipt{VectorSceneReceipt{source_items:p.copied_items,copied_bytes:p.copied_bytes,retained_capacity_bytes:p.retained_capacity_bytes,released_bytes:p.released_bytes}}
fn local(a:[f64;6])->DrawingAffine{DrawingAffine{xx:a[0],yx:a[1],xy:a[2],yy:a[3],dx:a[4],dy:a[5]}}
impl DrawingPlanCursor{
 const HEADER:usize=std::mem::size_of::<Self>()*2;
 fn fixed(&self)->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER+std::mem::size_of::<Frame>()*2,depth:self.frames.len().saturating_add(1),..Default::default()}}
 pub fn new(address:DrawingSourceAddress,placement:DrawingPlacement,target:LayoutBounds)->Self{Self{address,placement,target,preparation:None,phase:Phase::Birth,frames:PagedList::new(),pending:None,root:0,leaf:0,text_index:0,measuring:true,bounds:None,fit:DrawingAffine::identity(),path:Default::default(),asset:0,sample:None,last:Default::default(),closing:false,closed:false}}
 pub fn source_address(&self)->DrawingSourceAddress{self.address}
 pub fn last_receipt(&self)->VectorSceneReceipt{self.last}
 pub fn next_source_item_demand(&self)->usize{self.frames.len().saturating_add(2)}
 fn failure(&mut self,error:ValueError)->ValueError{self.pay(error.retained_progress());error.with_retained_progress(RetainedCloneProgress{copied_items:self.last.source_items,copied_bytes:self.last.copied_bytes,retained_capacity_bytes:self.last.retained_capacity_bytes,released_bytes:self.last.released_bytes})}
 pub fn measured_bounds(&self)->Option<DrawingBounds>{self.bounds}
 pub fn fitted_affine(&self)->DrawingAffine{self.fit}
 fn source(f:Frame)->DrawingSource{DrawingSource{layer:f.layer,leaf:f.leaf}}
 fn paint(f:Frame,node:&VectorNodeRef<'_>)->DrawingPaint{let fill=match node.paint.fill(){Some(VectorFillHead::Solid{color})=>Some(color),_=>None};let stroke=node.paint.stroke();let scale=|c:[f64;4]|[c[0],c[1],c[2],c[3]*f.opacity];DrawingPaint{fill:fill.map(scale),stroke:stroke.map(|s|scale(s.color)),stroke_width:stroke.map_or(0.0,|s|s.width),fill_rule:node.paint.fill_rule(),stroke_cap:stroke.map_or("round",|s|s.cap),stroke_join:stroke.map_or("round",|s|s.join)}}
 fn affine(&self,f:Frame)->Result<DrawingAffine,ValueError>{if self.measuring{Ok(f.affine)}else{f.affine.then(self.fit)}}
 fn include(&mut self,b:DrawingBounds){if let Some(bounds)=self.bounds.as_mut(){bounds.union(b)}else{self.bounds=Some(b)}}
 fn nested(&self,d:RetirementDemand)->Result<RetirementDemand,ValueError>{let own=self.fixed();Ok(RetirementDemand{copy_bytes:own.copy_bytes.checked_add(d.copy_bytes).ok_or_else(||invalid("Drawing demand overflow"))?,depth:own.depth.max(d.depth.saturating_add(1)),..d})}
 fn remaining(&self,grant:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes.saturating_sub(self.fixed().copy_bytes),maximum_depth:grant.maximum_depth.saturating_sub(1),maximum_items:grant.maximum_items.saturating_sub(self.frames.len().saturating_add(1)),..grant}}
 fn pay(&mut self,p:RetainedCloneProgress){let own=self.fixed();self.last=receipt(p);self.last.source_items=self.last.source_items.saturating_add(self.frames.len().saturating_add(1));self.last.copied_bytes=self.last.copied_bytes.saturating_add(own.copy_bytes)}
 /// 🎟️ No provider lookup occurs in this quote; the original read has already been routed and paid by its caller.
 pub fn next_demand(&self,read:&ChildAdmissionRead<'_>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid("Drawing plan is closing"))}match self.phase{Phase::Birth=>self.nested(OriginalChildVectorPreparation::birth_demand()),Phase::Prepare=>self.nested(self.preparation.as_ref().unwrap().next_demand(read,body.saturating_sub(self.fixed().copy_bytes))?),Phase::Push=>{if self.frames.has_reserved_slot(){Ok(self.fixed())}else{self.nested(RetirementDemand{copy_bytes:self.frames.next_reserve_copy_byte_demand()?,capacity_bytes:self.frames.next_allocation_bytes()?,depth:self.frames.next_reserve_depth_demand()?,..Default::default()})}},Phase::Walk|Phase::Assets=>self.nested(self.preparation.as_ref().unwrap().next_demand(read,body.saturating_sub(self.fixed().copy_bytes))?),Phase::Done=>Ok(self.fixed())}}
 fn node<'a>(&self,graph:&'a dyn VectorGraphSourceV1)->Result<&'a dyn VectorNodeSourceV1,ValueError>{let first=self.frames.get(0).ok_or_else(||invalid("Drawing frame route is empty"))?;let mut node=graph.root(first.route).ok_or_else(||invalid("Drawing graph root is missing"))?;for at in 1..self.frames.len(){node=node.child(self.frames.get(at).unwrap().route).ok_or_else(||invalid("Drawing graph child is missing"))?}Ok(node)}
 fn queue(&mut self,route:usize,layer:usize,parent:Option<Frame>){self.pending=Some(Frame{route,children:0,affine:parent.map_or(DrawingAffine::identity(),|p|p.affine),visible:parent.map_or(true,|p|p.visible),opacity:parent.map_or(1.0,|p|p.opacity),stage:0,at:0,layer,leaf:self.leaf,text:usize::MAX,origin:VectorPoint2{x:0.0,y:0.0}});self.leaf+=1;self.phase=Phase::Push}
 /// 🧵️ Original admission is fully closed before the first typed descriptor can be read.
 pub fn advance<'a>(&mut self,read:&ChildAdmissionRead<'a>,grant:VectorSceneGrant)->Result<DrawingPlanTurn<'a>,ValueError>{self.last=Default::default();let demand=self.next_demand(read,grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(g(grant),demand)||grant.maximum_source_items<=self.frames.len().saturating_add(1){return Ok(DrawingPlanTurn::Progress)}let child=self.remaining(g(grant));match self.phase{Phase::Birth=>{let(owner,p)=OriginalChildVectorPreparation::admit(child).map_err(|error|self.failure(error))?;self.preparation=Some(owner);self.pay(p);self.phase=Phase::Prepare;return Ok(DrawingPlanTurn::Progress)},Phase::Prepare=>{let step=self.preparation.as_mut().unwrap().advance(read,child).map_err(|error|self.failure(error))?;self.pay(step.progress);if step.done{if let Some(error)=step.error{return Err(invalid(error))}if step.graph.is_none(){return Err(invalid("Drawing original graph missing"))}self.phase=Phase::Walk}return Ok(DrawingPlanTurn::Progress)},Phase::Push=>{if !self.frames.has_reserved_slot(){let p=self.frames.reserve_one_funded(child).map_err(|e|e.refusal())?;self.pay(p);return Ok(DrawingPlanTurn::Progress)}let frame=self.pending.take().ok_or_else(||invalid("Drawing pending frame missing"))?;self.frames.push_reserved(frame).map_err(|_|invalid("Drawing original frame slot missing"))?;self.pay(Default::default());self.phase=Phase::Walk;return Ok(DrawingPlanTurn::Progress)},Phase::Done=>{self.pay(Default::default());return Ok(DrawingPlanTurn::Done)},_=>{}}
 let step=self.preparation.as_mut().unwrap().advance(read,child).map_err(|error|self.failure(error))?;self.pay(step.progress);if !step.done{return Ok(DrawingPlanTurn::Progress)}let graph=step.graph.ok_or_else(||invalid("Drawing original graph missing"))?;if self.phase==Phase::Assets{if self.asset==graph.asset_count(){self.phase=Phase::Done;return Ok(DrawingPlanTurn::Done)}let value=graph.asset(self.asset).ok_or_else(||invalid("Drawing original asset missing"))?;if let Some(index)=self.sample{if index<value.samples.sample_count(){let sample=value.samples.sample(index).ok_or_else(||invalid("Drawing original sample missing"))?;self.sample=Some(index+1);return Ok(DrawingPlanTurn::Semantic(DrawingSemanticEvent::Sample{asset:self.asset,index,value:sample}))}self.asset+=1;self.sample=None;return Ok(DrawingPlanTurn::Progress)}self.sample=Some(0);return Ok(DrawingPlanTurn::Semantic(DrawingSemanticEvent::Asset{index:self.asset,value}))}
 if self.frames.is_empty(){if self.root<graph.root_count(){let route=self.root;self.root+=1;self.queue(route,route,None);return Ok(DrawingPlanTurn::Progress)}if self.measuring{if self.placement==DrawingPlacement::Canvas{let canvas=graph.canvas().ok_or_else(||invalid("Drawing canvas missing"))?;self.bounds=Some(DrawingBounds{left:0.0,top:0.0,right:canvas.width,bottom:canvas.height});self.fit=DrawingAffine::canvas(canvas,&self.target)?}else{self.fit=self.bounds.map(|b|DrawingAffine::fit(b,&self.target)).transpose()?.unwrap_or_else(DrawingAffine::identity)}self.root=0;self.leaf=0;self.text_index=0;self.measuring=false;return Ok(DrawingPlanTurn::Fitted{bounds:self.bounds,affine:self.fit})}self.phase=Phase::Assets;return Ok(DrawingPlanTurn::Progress)}
 let source=self.node(graph)?;let node=source.descriptor();let at=self.frames.len()-1;let mut f=*self.frames.get(at).unwrap();let mut out=DrawingPlanTurn::Progress;match f.stage{0=>{f.affine=local(node.transform).then(f.affine)?;f.visible&=node.visible;f.opacity*=node.opacity;f.children=source.child_count();f.stage=1;f.at=0;if !self.measuring{out=DrawingPlanTurn::Semantic(DrawingSemanticEvent::Node{source:Self::source(f),affine:self.affine(f)?,opacity:f.opacity,visible:f.visible,node})}},1=>{if f.at<node.paint.stop_count(){let index=f.at;f.at+=1;let value=node.paint.stop(index).ok_or_else(||invalid("Drawing gradient stop missing"))?;if !self.measuring{out=DrawingPlanTurn::Semantic(DrawingSemanticEvent::Stop{source:Self::source(f),index,value})}}else{f.stage=2;f.at=0}},2=>{if f.at<node.paint.dash_count(){let index=f.at;f.at+=1;let value=node.paint.dash(index).ok_or_else(||invalid("Drawing dash missing"))?;if !self.measuring{out=DrawingPlanTurn::Semantic(DrawingSemanticEvent::Dash{source:Self::source(f),index,value})}}else{f.stage=3;f.at=0}},3=>{if f.at<source.reference_count(){let index=f.at;f.at+=1;let value=source.reference(index).ok_or_else(||invalid("Drawing boolean reference missing"))?;if !self.measuring{out=DrawingPlanTurn::Semantic(DrawingSemanticEvent::Reference{source:Self::source(f),index,value})}}else{f.stage=4;f.at=0}},4=>{f.stage=7;f.at=0;if f.visible{match &node.content{VectorContentRef::Path(_)|VectorContentRef::Shape(_)=>{f.stage=5;self.path=Default::default();if !self.measuring{out=DrawingPlanTurn::Primitive(DrawingPrimitive::BeginPath{source:Self::source(f),paint:Self::paint(f,&node),affine:self.affine(f)?})}},VectorContentRef::Text{x,y,..}=>{f.origin=VectorPoint2{x:*x,y:*y};f.text=self.text_index;self.text_index+=1;if self.measuring{f.stage=6;out=DrawingPlanTurn::MeasureText(self.make_text(f,node)?)}else{out=DrawingPlanTurn::Primitive(DrawingPrimitive::Text(self.make_text(f,node)?))}},VectorContentRef::Image{width,height,..}=>{if self.measuring{self.include(DrawingBounds{left:0.0,top:0.0,right:*width,bottom:*height}.transformed(f.affine)?)}else{out=DrawingPlanTurn::Primitive(DrawingPrimitive::Resolve{source:Self::source(f),affine:self.affine(f)?,node,graph})}},VectorContentRef::Boolean{..}|VectorContentRef::Trace{..}=>{if self.measuring&&self.placement==DrawingPlacement::Content{return Err(invalid("Drawing content extent requires boolean or tracing resolution"))}if !self.measuring{out=DrawingPlanTurn::Primitive(DrawingPrimitive::Resolve{source:Self::source(f),affine:self.affine(f)?,node,graph})}},VectorContentRef::Group{..}=>{}}}},5=>{let segment=match &node.content{VectorContentRef::Path(path)=>if f.at<path.segment_count(){path.segment(f.at)}else{None},VectorContentRef::Shape(shape)=>shape.primitive().and_then(|shape|shape_segment(shape,f.at)),_=>return Err(invalid("Drawing path descriptor changed"))};if let Some(segment)=segment{f.at+=1;if self.measuring{self.path.segment(segment,f.affine)?}else{out=DrawingPlanTurn::Primitive(DrawingPrimitive::Segment{source:Self::source(f),segment,affine:self.affine(f)?})}}else{if self.measuring{if let Some(bounds)=self.path.bounds{self.include(bounds)}}f.stage=7;f.at=0;if !self.measuring{out=DrawingPlanTurn::Primitive(DrawingPrimitive::EndPath{source:Self::source(f)})}}},6=>{out=DrawingPlanTurn::MeasureText(self.make_text(f,node)?)},7=>{if f.at<f.children{let child=f.at;f.at+=1;self.queue(child,f.layer,Some(f))}else{f.stage=8}},8=>{self.frames.pop();if !self.measuring{out=DrawingPlanTurn::Semantic(DrawingSemanticEvent::EndNode{source:Self::source(f),node})}return Ok(out)},_=>return Err(invalid("Drawing traversal stage invalid"))}*self.frames.get_mut(at).unwrap()=f;Ok(out)}
 fn make_text<'a>(&self,f:Frame,node:VectorNodeRef<'a>)->Result<DrawingTextPlan<'a>,ValueError>{let paint=Self::paint(f,&node);let VectorContentRef::Text{content,x,y,size,font_family}=node.content else{return Err(invalid("Drawing text descriptor changed"))};Ok(DrawingTextPlan{source:Self::source(f),index:f.text,content,at:VectorPoint2{x,y},affine:self.affine(f)?,paint,font:DrawingFont{family:font_family,weight:400,size,leading:size*1.2,tracking:0.0}})}
 pub fn text<'a>(&mut self,read:&ChildAdmissionRead<'a>,index:usize,grant:VectorSceneGrant)->Result<DrawingTextPlan<'a>,ValueError>{self.last=Default::default();let demand=self.nested(self.preparation.as_ref().unwrap().next_demand(read,grant.maximum_copy_bytes.saturating_sub(self.fixed().copy_bytes))?)?;if !retained_clone_grant_admits(g(grant),demand)||grant.maximum_source_items<=self.frames.len()+1{return Err(invalid("Drawing text loan is unfunded"))}let child=self.remaining(g(grant));let result=self.preparation.as_mut().unwrap().advance(read,child).map_err(|error|self.failure(error))?;self.pay(result.progress);let graph=result.graph.ok_or_else(||invalid("Drawing graph missing"))?;let f=*self.frames.last().ok_or_else(||invalid("Drawing text frame missing"))?;if f.text!=index{return Err(invalid("Drawing active text changed"))}self.make_text(f,self.node(graph)?.descriptor())}
 pub fn include_text_extent(&mut self,index:usize,bounds:Option<DrawingBounds>)->Result<(),ValueError>{let at=self.frames.len().checked_sub(1).ok_or_else(||invalid("Drawing active text missing"))?;let mut f=*self.frames.get(at).unwrap();if !self.measuring||f.stage!=6||f.text!=index{return Err(invalid("Drawing glyph extent does not match active text"))}if let Some(mut bounds)=bounds{bounds.left+=f.origin.x;bounds.right+=f.origin.x;bounds.top+=f.origin.y;bounds.bottom+=f.origin.y;self.include(bounds.transformed(f.affine)?)}f.stage=7;f.at=0;*self.frames.get_mut(at).unwrap()=f;Ok(())}
 pub fn begin_close(&mut self){self.closing=true}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.closed{return Ok(Default::default())}if !self.frames.is_empty(){return Ok(self.fixed())}if !self.frames.terminal_is_empty(){return self.nested(RetirementDemand{release_bytes:self.frames.next_release_allocation_bytes()?,depth:1,..Default::default()})}if let Some(owner)=self.preparation.as_ref(){return self.nested(owner.close_demand(body.saturating_sub(self.fixed().copy_bytes))?)}Ok(self.fixed())}
 pub fn close_step(&mut self,grant:VectorSceneGrant)->Result<bool,ValueError>{self.last=Default::default();if !self.closing{return Err(invalid("Drawing close has not begun"))}if self.closed{return Ok(false)}let d=self.close_demand(grant.maximum_copy_bytes)?;if !retained_clone_grant_admits(g(grant),d)||grant.maximum_source_items<=self.frames.len()+1{return Ok(false)}if !self.frames.is_empty(){self.frames.pop();self.pay(Default::default());return Ok(true)}if !self.frames.terminal_is_empty(){let p=self.frames.release_empty_page(grant.maximum_release_bytes)?;self.pay(RetainedCloneProgress{released_bytes:p.released_allocation_bytes,..Default::default()});return Ok(p.progressed)}let child=self.remaining(g(grant));if let Some(owner)=self.preparation.as_mut(){owner.begin_close();let result=owner.close_step(child);let empty=owner.terminal_is_empty();let p=result.map_err(|error|self.failure(error))?.progress();if empty{self.preparation=None}self.pay(p);return Ok(true)}self.pending=None;self.closed=true;self.pay(Default::default());Ok(true)}
 pub fn next_release_bytes(&self)->usize{self.close_demand(0).map_or(0,|d|d.release_bytes)}
 pub fn terminal_is_empty(&self)->bool{self.closed&&self.frames.terminal_is_empty()&&self.preparation.is_none()&&self.pending.is_none()}
}
impl Drop for DrawingPlanCursor{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Drawing plans require original funded closure")}}
fn shape_segment(shape:VectorShapeRef<'_>,at:usize)->Option<VectorSegment>{let p=|x,y|VectorPoint2{x,y};match shape{VectorShapeRef::Rect{x,y,width,height}=>match at{0=>Some(VectorSegment::MoveTo{to:p(x,y)}),1=>Some(VectorSegment::LineTo{to:p(x+width,y)}),2=>Some(VectorSegment::LineTo{to:p(x+width,y+height)}),3=>Some(VectorSegment::LineTo{to:p(x,y+height)}),4=>Some(VectorSegment::Close),_=>None},VectorShapeRef::Line{x1,y1,x2,y2}=>match at{0=>Some(VectorSegment::MoveTo{to:p(x1,y1)}),1=>Some(VectorSegment::LineTo{to:p(x2,y2)}),_=>None},VectorShapeRef::Polygon(source)=>if at==source.point_count(){Some(VectorSegment::Close)}else{source.point(at).map(|v|if at==0{VectorSegment::MoveTo{to:p(v[0],v[1])}}else{VectorSegment::LineTo{to:p(v[0],v[1])}})},VectorShapeRef::Circle{cx,cy,r}=>ellipse_segment(cx,cy,r,r,at),VectorShapeRef::Ellipse{cx,cy,rx,ry}=>ellipse_segment(cx,cy,rx,ry,at)}}
fn ellipse_segment(cx:f64,cy:f64,rx:f64,ry:f64,at:usize)->Option<VectorSegment>{Some(match at{0=>VectorSegment::MoveTo{to:VectorPoint2{x:cx+rx,y:cy}},1|2=>VectorSegment::ArcTo{rx,ry,x_rotation:0.0,large_arc:false,sweep:true,to:VectorPoint2{x:cx+if at==1{-rx}else{rx},y:cy}},3=>VectorSegment::Close,_=>return None})}
